   566  /**
   567   * xmlParserGrow:
   568   * @ctxt:  an XML parser context
   569   *
   570   * Grow the input buffer.
   571   *
   572   * Returns the number of bytes read or -1 in case of error.
   573   */
   574  int
   575  xmlParserGrow(xmlParserCtxtPtr ctxt) {
   576      xmlParserInputPtr in = ctxt->input;
   577      xmlParserInputBufferPtr buf = in->buf;
   578      ptrdiff_t curEnd = in->end - in->cur;
   579      ptrdiff_t curBase = in->cur - in->base;
   580      int ret;
   581
   582      if (buf == NULL)
   583          return(0);
   584      /* Don't grow push parser buffer. */
   585      if ((ctxt->progressive) && (ctxt->inputNr <= 1))
   586          return(0);
   587      if (buf->error != 0)
   588          return(-1);
   589
   590      if (((curEnd > XML_MAX_LOOKUP_LIMIT) ||
   591           (curBase > XML_MAX_LOOKUP_LIMIT)) &&
   592          ((ctxt->options & XML_PARSE_HUGE) == 0)) {
   593          xmlFatalErr(ctxt, XML_ERR_RESOURCE_LIMIT,
   594                      "Buffer size limit exceeded, try XML_PARSE_HUGE\n");
   595          xmlHaltParser(ctxt);
   596          return(-1);
   597      }
   598
   599      if (curEnd >= INPUT_CHUNK)
   600          return(0);
   601
   602      ret = xmlParserInputBufferGrow(buf, INPUT_CHUNK);
   603      xmlBufUpdateInput(buf->buffer, in, curBase);
   604
   605      if (ret < 0) {
   606          xmlFatalErr(ctxt, buf->error, NULL);
   607      }
   608
   609      return(ret);
   610  }
