   655  /**
   656   * xmlParserShrink:
   657   * @ctxt:  an XML parser context
   658   *
   659   * Shrink the input buffer.
   660   */
   661  void
   662  xmlParserShrink(xmlParserCtxtPtr ctxt) {
   663      xmlParserInputPtr in = ctxt->input;
   664      xmlParserInputBufferPtr buf = in->buf;
   665      size_t used;
   666
   667      if (buf == NULL)
   668          return;
   669
   670      used = in->cur - in->base;
   671      /*
   672       * Do not shrink on large buffers whose only a tiny fraction
   673       * was consumed
   674       */
   675      if (used > INPUT_CHUNK) {
   676          size_t res = xmlBufShrink(buf->buffer, used - LINE_LEN);
   677
   678          if (res > 0) {
   679              used -= res;
   680              if ((res > ULONG_MAX) ||
   681                  (in->consumed > ULONG_MAX - (unsigned long)res))
   682                  in->consumed = ULONG_MAX;
   683              else
   684                  in->consumed += res;
   685          }
   686      }
   687
   688      xmlBufUpdateInput(buf->buffer, in, used);
   689  }
