   691  /**
   692   * xmlParserInputShrink:
   693   * @in:  an XML parser input
   694   *
   695   * DEPRECATED: Don't use.
   696   *
   697   * This function removes used input for the parser.
   698   */
   699  void
   700  xmlParserInputShrink(xmlParserInputPtr in) {
   701      size_t used;
   702      size_t ret;
   703
   704      if (in == NULL) return;
   705      if (in->buf == NULL) return;
   706      if (in->base == NULL) return;
   707      if (in->cur == NULL) return;
   708      if (in->buf->buffer == NULL) return;
   709
   710      used = in->cur - in->base;
   711      /*
   712       * Do not shrink on large buffers whose only a tiny fraction
   713       * was consumed
   714       */
   715      if (used > INPUT_CHUNK) {
   716          ret = xmlBufShrink(in->buf->buffer, used - LINE_LEN);
   717          if (ret > 0) {
   718              used -= ret;
   719              if ((ret > ULONG_MAX) ||
   720                  (in->consumed > ULONG_MAX - (unsigned long)ret))
   721                  in->consumed = ULONG_MAX;
   722              else
   723                  in->consumed += ret;
   724          }
   725      }
   726
   727      if (xmlBufUse(in->buf->buffer) <= INPUT_CHUNK) {
   728          xmlParserInputBufferRead(in->buf, 2 * INPUT_CHUNK);
   729      }
   730
   731      in->base = xmlBufContent(in->buf->buffer);
   732      if (in->base == NULL) {
   733          /* TODO: raise error */
   734          in->base = BAD_CAST "";
   735          in->cur = in->base;
   736          in->end = in->base;
   737          return;
   738      }
   739      in->cur = in->base + used;
   740      in->end = xmlBufEnd(in->buf->buffer);
   741  }
